CREATE TABLE IF NOT EXISTS hr_payroll_accounting_config(config_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,salary_expense_ledger TEXT NOT NULL DEFAULT 'SALARY_EXPENSE',salary_payable_ledger TEXT NOT NULL DEFAULT 'SALARY_PAYABLE',employer_statutory_ledger TEXT NOT NULL DEFAULT 'EMPLOYER_STATUTORY_PAYABLE',employee_advance_ledger TEXT NOT NULL DEFAULT 'EMPLOYEE_ADVANCES',payroll_clearing_ledger TEXT NOT NULL DEFAULT 'PAYROLL_CLEARING',production_labour_ledger TEXT NOT NULL DEFAULT 'PRODUCTION_LABOUR',UNIQUE(organization_id,entity_id));
CREATE TABLE IF NOT EXISTS hr_payroll_accounting_journal(journal_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,run_id TEXT NOT NULL,journal_type TEXT NOT NULL,voucher_no TEXT NOT NULL,journal_date TEXT NOT NULL,debit_total NUMERIC NOT NULL DEFAULT 0,credit_total NUMERIC NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'POSTED',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(run_id,journal_type));
CREATE TABLE IF NOT EXISTS hr_payroll_accounting_line(line_id TEXT PRIMARY KEY,journal_id TEXT NOT NULL,ledger_code TEXT NOT NULL,debit NUMERIC NOT NULL DEFAULT 0,credit NUMERIC NOT NULL DEFAULT 0,employee_id TEXT,department_id TEXT,production_batch_id TEXT,narration TEXT);
CREATE TABLE IF NOT EXISTS hr_payroll_expense_allocation(allocation_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,department_id TEXT NOT NULL,amount NUMERIC NOT NULL,basis TEXT NOT NULL DEFAULT 'MANUAL',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(run_id,department_id));
CREATE TABLE IF NOT EXISTS hr_payroll_employee_recovery(recovery_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,employee_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,recovery_type TEXT NOT NULL,amount NUMERIC NOT NULL,ledger_code TEXT NOT NULL DEFAULT 'EMPLOYEE_ADVANCES',status TEXT NOT NULL DEFAULT 'OPEN',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hr_payroll_accounting_reconciliation(reconciliation_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,payroll_net NUMERIC NOT NULL,bank_paid NUMERIC NOT NULL,statutory_payable NUMERIC NOT NULL,gl_salary NUMERIC NOT NULL,gl_payable NUMERIC NOT NULL,difference NUMERIC NOT NULL,status TEXT NOT NULL DEFAULT 'EXCEPTION',notes TEXT,reconciled_by TEXT,reconciled_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(run_id));
CREATE TABLE IF NOT EXISTS hr_payroll_month_close(close_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,period_id TEXT NOT NULL,run_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',closed_by TEXT,closed_at TIMESTAMP,notes TEXT,UNIQUE(organization_id,entity_id,period_id));
